def normalize_timestamp(ts_str):
    """
    Converts an ISO format string to a normalized ISO format string.
    If the input string is naive (lacks timezone info), it is treated as UTC.
    """
    from datetime import timezone
    dt = datetime.fromisoformat(ts_str)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.isoformat()
